     1→# ABOUTME: Global Value Numbering optimization pass for Sea of Nodes IR
     2→# ABOUTME: Implements GVN for common subexpression elimination and redundant computation removal
     3→
     4→use 5.42.0;
     5→use experimental qw(class builtin keyword_any keyword_all);
     6→use utf8;
     7→
     8→class Chalk::IR::Optimizer::GVN {
     9→    use Chalk::IR::Node;
    10→    use Chalk::IR::Graph;
    11→
    12→    # Instance method for pipeline compatibility
    13→    # Returns optimized graph (not a hashref)
    14→    method apply($graph) {
    15→        my $result = $self->run_gvn($graph);
    16→        return $result->{graph};
    17→    }
    18→
    19→    # Run Global Value Numbering optimization pass
    20→    # Returns: { graph => optimized_graph, metrics => { nodes_eliminated => N, redirections => {...} } }
    21→    sub run_gvn($class, $graph) {
    22→        # Value number tracking: value_number => canonical_node_id
    23→        my $value_to_node = {};
    24→
    25→        # Node to value number mapping: node_id => value_number
    26→        my $node_to_value = {};
    27→
    28→        # Redirection map: duplicate_node_id => canonical_node_id
    29→        my $redirections = {};
    30→
    31→        # Get all nodes in a consistent order (we'll process them by ID order)
    32→        my @node_ids = sort keys %{$graph->nodes};
    33→
    34→        # Phase 1: Compute value numbers for all nodes
    35→        for my $node_id (@node_ids) {
    36→            my $node = $graph->get_node($node_id);
    37→            next unless defined($node);
    38→
    39→            # Compute value number for this node
    40→            my $value_num = $class->_compute_value_number($node, $node_to_value, $graph);
    41→
    42→            # Check if we've seen this value number before
    43→            if (exists($value_to_node->{$value_num})) {
    44→                # Found a duplicate! Record the redirection
    45→                my $canonical_id = $value_to_node->{$value_num};
    46→                $redirections->{$node_id} = $canonical_id;
    47→                # Use the canonical node's value number for this node too
    48→                $node_to_value->{$node_id} = $value_num;
    49→            } else {
    50→                # First time seeing this value - this is the canonical node
    51→                $value_to_node->{$value_num} = $node_id;
    52→                $node_to_value->{$node_id} = $value_num;
    53→            }
    54→        }
    55→
    56→        # Phase 2: Build new graph with redirections applied
    57→        my $new_graph = Chalk::IR::Graph->new();
    58→
    59→        # Track which nodes have been copied to new graph
    60→        my %copied;
    61→
    62→        # Copy nodes that aren't redirected, applying redirections to inputs
    63→        for my $node_id (@node_ids) {
    64→            # Skip nodes that are being redirected away
    65→            next if exists($redirections->{$node_id});
    66→
    67→            my $old_node = $graph->get_node($node_id);
    68→            next unless defined($old_node);
    69→
    70→            # Apply redirections to input list
    71→            my @new_inputs;
    72→            for my $input_id ($old_node->inputs->@*) {
    73→                if (defined($input_id)) {
    74→                    # Follow redirection chain if this input was redirected
    75→                    my $final_id = $class->_follow_redirections($input_id, $redirections);
    76→                    push @new_inputs, $final_id;
    77→                } else {
    78→                    push @new_inputs, undef;
    79→                }
    80→            }
    81→
    82→            # Apply redirections to attributes (if they contain node references)
    83→            my $new_attributes = $class->_redirect_attributes(
    84→                $old_node->attributes,
    85→                $redirections
    86→            );
    87→
    88→            # Create new node with redirected inputs
    89→            my $new_node = Chalk::IR::Node->new(
    90→                id         => $node_id,
    91→                op         => $old_node->op,
    92→                inputs     => \@new_inputs,
    93→                attributes => $new_attributes,
    94→            );
    95→
    96→            $new_graph->add_node($new_node);
    97→            $copied{$node_id} = 1;
    98→        }
    99→
   100→        # Preserve entry point (following any redirection)
   101→        if (defined($graph->entry)) {
   102→            my $new_entry = $class->_follow_redirections($graph->entry, $redirections);
   103→            $new_graph->set_entry($new_entry);
   104→        }
   105→
   106→        # Compute metrics
   107→        my $nodes_eliminated = scalar keys %{$redirections};
   108→
   109→        return {
   110→            graph => $new_graph,
   111→            metrics => {
   112→                nodes_eliminated => $nodes_eliminated,
   113→                redirections => $redirections,
   114→            }
   115→        };
   116→    }
   117→
   118→    # Compute value number for a node
   119→    # Returns a string that uniquely identifies the value computed by this node
   120→    sub _compute_value_number($class, $node, $node_to_value, $graph) {
   121→        my $op = $node->op;
   122→        my $attrs = $node->attributes;
   123→
   124→        # Special case: Constants
   125→        if ($op eq 'Constant') {
   126→            my $value = $attrs->{value} // '';
   127→            my $type = $attrs->{type} // '';
   128→            return "Constant:$value:$type";
   129→        }
   130→
   131→        # Special case: Proj nodes (include index)
   132→        if ($op eq 'Proj') {
   133→            my $index = $attrs->{index} // '';
   134→            # Get value number of input node
   135→            my @input_vns;
   136→            for my $input_id ($node->inputs->@*) {
   137→                if (defined($input_id) && exists($node_to_value->{$input_id})) {
   138→                    push @input_vns, $node_to_value->{$input_id};
   139→                } else {
   140→                    push @input_vns, $input_id // 'undef';
   141→                }
   142→            }
   143→            my $inputs_str = join(',', @input_vns);
   144→            return "Proj:$index:$inputs_str";
   145→        }
   146→
   147→        # Special case: Phi nodes - use identity-based comparison
